def separate_paren_groups(paren_string: str) -> List[str]:
    cleaned = ''.join(char for char in paren_string if char != ' ')
    result = []
    current_group = ''

    for char in cleaned:
        if char == '(':
            current_group += char
        elif char == ')':
            current_group += char
            if not is_balanced(current_group):
                while len(result) > 0 and not is_balanced(result[-1]):
                    result.pop()
                result.append(current_group)
                current_group = ''

    return result


def is_balanced(s: str) -> bool:
    count = 0
    for char in s:
        if char == '(':
            count += 1
        elif char == ')':
            count -= 1
            if count < 0:
                return False
    return count == 0
